        display: grid;
        gap: 1rem;
      }

      .example {
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 1.2rem;
        background: linear-gradient(145deg, var(--panel), var(--panel-alt));
        box-shadow: 0 1.25rem 3rem var(--shadow);
      }

      .question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        width: 100%;
        gap: 1rem;
        border: 0;
        padding: 1.25rem 1.4rem;
        color: var(--text);
        background: transparent;
        font: inherit;
        font-size: 1.05rem;
        font-weight: 700;
        text-align: left;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(255, 255, 255, 0.04);
      }

      .question:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: -3px;
      }

      .icon {
        display: grid;
        place-items: center;
        flex: 0 0 auto;
        width: 2rem;
        height: 2rem;
        border-radius: 999px;
        color: #10131a;
