         padding: 0 1.4rem 1.35rem;
         color: var(--muted);
       }

       .details[hidden] {
         display: none;
       }

       .details p {
         margin: 0;
       }

       @media (max-width: 42rem) {
         main {
           width: min(100% - 1rem, 56rem);
           padding: 2rem 0;
         }

         .question {
           padding: 1.1rem;
         }

         .details {
           padding: 0 1.1rem 1.2rem;
         }
       }
     </style>
   </head>
   <body>
     <main>
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Feline essentials</p>
         <h1 id="page-title">Cat FAQ</h1>
         <p class="intro">
           Quick answers for curious cat people, from purring mysteries to daily care basics.
         </p>
       </section>

       <section class="faq" aria-label="Frequently asked questions about cats">
         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
             <span>Why do cats purr?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
             <p>
               Cats often purr when they feel relaxed, but purring can also happen when they want comfort,
               are healing, or are asking for attention.
             </p>
           </div>
         </div>

         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
             <span>How much sleep do cats need?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-2" role="region" aria-labelledby="question-2" hidden>
             <p>
               Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer
               because growth and recovery require extra rest.
             </p>
           </div>
         </div>

         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
             <span>Why does my cat knead blankets?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-3" role="region" aria-labelledby="question-3" hidden>
             <p>
               Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead soft
               surfaces when they feel safe, content, or ready to settle in.
             </p>
           </div>
         </div>

         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
             <span>Do indoor cats need playtime?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-4" role="region" aria-labelledby="question-4" hidden>
             <p>
               Yes. Daily interactive play helps indoor cats exercise, practice natural hunting behaviors,
               reduce boredom, and build trust with their people.
             </p>
           </div>
         </div>

         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-5" id="question-5">
             <span>How can I tell if a cat is comfortable?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-5" role="region" aria-labelledby="question-5" hidden>
             <p>
               A comfortable cat may have relaxed ears, soft eyes, loose posture, slow blinking, gentle
               purring, or a tail held calmly upright.
             </p>
           </div>
         </div>
       </section>
     </main>

     <script>
       const questions = document.querySelectorAll(".question");

       questions.forEach((question) => {
         question.addEventListener("click", () => {
           const answer = document.getElementById(question.getAttribute("aria-controls"));
           const isExpanded = question.getAttribute("aria-expanded") === "true";

           question.setAttribute("aria-expanded", String(!isExpanded));
           answer.hidden = isExpanded;
         });
       });
     </script>
   </body>
 </html>

')
